import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { Product } from 'src/app/model/Product';
import { AuthService } from 'src/app/services/auth.service';
import { ProductService } from 'src/app/services/product.service';
import { CartService } from 'src/app/services/cart.service';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit {

  products: Product[] = [];
  allProducts: Product[] = [];
  cart: Product[] = [];

  constructor(
    private router: Router,
    private authService: AuthService,
    private productService: ProductService,
    private cartService: CartService
  ) {}

  ngOnInit(): void {
    this.loadProducts();
  }

  // Load all products initially
  loadProducts(): void {
    this.productService.listAllProducts().subscribe({
      next: (response: any[]) => {
        console.log('All products:', response);
        this.products = response.map(this.mapProduct);
        this.allProducts = [...this.products];
      },
      error: (err) => console.error('Failed to load products:', err)
    });
  }

  // Map API response to Product object
  private mapProduct(p: any): Product {
    return {
      id: p.productId,
      title: p.title,
      description: p.description,
      quantity: p.availableQuantity,
      price: p.price,
      category: p.category,
      categoryId: p.categoryId
    };
  }

  // Called whenever filters are changed in header
  onFiltersChanged(filters: any): void {
    console.log('Filters received in Home:', filters);


const categoryId = filters.selectedCategory || '';
    const minPrice = 0;
    const maxPrice = filters.maxPrice ?? 5000;
    const sortBy = filters.sortBy || '';
    const searchText = filters.searchText?.trim() || '';


    const sortMapping: any = {
  lowToHigh: 'priceAsc',
  highToLow: 'priceDesc',
  newest: 'newest'
};

const sortParam = sortMapping[sortBy] || '';


    if (searchText) {
      // Search API call
      this.productService.searchProducts(searchText).subscribe({
        next: (response: any[]) => {
          console.log('Search results:', response);
          this.products = response.map(this.mapProduct);
        },
        error: (err) => console.error('Search API error:', err)
      });
      return;
    }

    // Filter + Sort API call
    this.productService.filterProducts(categoryId, minPrice, maxPrice, sort).subscribe({
      next: (response: any[]) => {
        console.log('Filtered products:', response);
        this.products = response.map(this.mapProduct);
      },
      error: (err) => console.error('Filter API error:', err)
    });
  }

  // Add product to cart
  addToCart(product: Product): void {
    if (!product?.id) {
      console.error('Invalid product ID:', product);
      return;
    }

    this.cartService.addToCart(product.id, 1).subscribe({
      next: () => alert(product.title + ' added to cart!'),
      error: (err) => alert('Failed to add to cart: ' + (err?.message || 'Unknown error'))
    });
  }

  // Navigate to product detail page
  viewDetailsEvent(productID: number): void {
    if (productID != null) {
      this.router.navigate(['/customer/product-detail', productID]);
    } else {
      alert('Product ID is missing!');
    }
  }
}
